public interface RepositorioTickets {
    Optional<Ticket> buscarPorId(long id);
    List<Ticket> listarPorStatus(String status, int limite);
    Ticket salvar(Ticket ticket);
}

public class ServicoTickets {
    private final RepositorioTickets repositorio;

    // a dependência entra pelo construtor: é o que permite trocar no teste
    public ServicoTickets(RepositorioTickets repositorio) {
        this.repositorio = repositorio;
    }

    public Ticket reabrir(long id, Usuario usuario) {
        Ticket ticket = repositorio.buscarPorId(id)
            .orElseThrow(() -> new TicketNaoEncontrado(id));

        if (!ticket.podeSerReabertoPor(usuario)) {
            throw new SemPermissao("reabrir ticket");
        }

        return repositorio.salvar(ticket.reabrir());
    }
}

